{"code": "python -c "
# Full LBO model with modified revenue growth

# Base case growth rates
base_growth = {
    1: 0.09595116957,
    2: 0.1411764706,
    3: 0.17,
    4: 0.20,
    5: 0.23
}

# Modified growth rates (relative decreases)
modified_growth = {}
for year, rate in base_growth.items():
    if year == 3:
        modified_growth[year] = rate * (1 - 0.05)
    elif year == 4:
        modified_growth[year] = rate * (1 - 0.10)
    elif year == 5:
        modified_growth[year] = rate * (1 - 0.15)
    else:
        modified_growth[year] = rate

# Pro-forma Total Revenue (in thousands)
pro_forma_revenue = 1700000

# Calculate revenues
revenues = {}
revenues[0] = pro_forma_revenue
for year in range(1, 6):
    revenues[year] = revenues[year-1] * (1 + modified_growth[year])

# Subscription % = 0.94 (constant)
sub_pct = 0.94

# Subscription revenues
sub_revenues = {}
for year in range(6):
    sub_revenues[year] = revenues[year] * sub_pct

# Services revenues
svc_revenues = {}
for year in range(6):
    svc_revenues[year] = revenues[year] * (1 - sub_pct)

# Cost of Revenue Schedule
# Subscription CoR %: 0.1757153966 (Year 0), then 0.1657153966 (Years 1-5)
# Services CoR %: 0.9838233417 (Year 0), then 0.9738233417 (Years 1-5)
sub_cor_pct = 0.1657153966
svc_cor_pct = 0.9738233417

sub_cor = {}
svc_cor = {}
total_cor = {}
for year in range(6):
    sub_cor[year] = sub_revenues[year] * sub_cor_pct
    svc_cor[year] = svc_revenues[year] * svc_cor_pct
    total_cor[year] = sub_cor[year] + svc_cor[year]

# Gross profit
gross_profit = {}
for year in range(6):
    gross_profit[year] = revenues[year] - total_cor[year]

# Operating Expenses as % of Total Revenues
RD_pct = 0.2485539891
SM_pct = 0.4086434445
GA_pct = 0.1143135091
Restr_pct = {0: 0.01, 1: 0.01, 2: 0.01, 3: 0.0, 4: 0.0, 5: 0.0}

rd_exp = {}
sm_exp = {}
ga_exp = {}
restr_exp = {}
total_opex = {}
for year in range(6):
    rd_exp[year] = revenues[year] * RD_pct
    sm_exp[year] = revenues[year] * SM_pct
    ga_exp[year] = revenues[year] * GA_pct
    restr_exp[year] = revenues[year] * Restr_pct[year]
    total_opex[year] = rd_exp[year] + sm_exp[year] + ga_exp[year] + restr_exp[year]

# EBITDA
EBITDA = {}
for year in range(6):
    EBITDA[year] = gross_profit[year] - total_opex[year]

# D&A (from model - proportional to revenues)
# Year 1: 110137.9884, Year 2: 117311.7277, Year 3: 137124.6714, Year 4: 164396.6057, Year 5: 202031.875
# These are from base case. Need to scale with revenue changes
base_revenues = [1700000, 1940000, 2269800, 2723760, 3350224.8]
base_DA = [110137.9884, 117311.7277, 137124.6714, 164396.6057, 202031.875]

DA = {}
for year in range(1, 6):
    ratio = revenues[year] / base_revenues[year-1]
    DA[year] = base_DA[year-1] * ratio

# EBIT
EBIT = {}
for year in range(6):
    EBIT[year] = EBITDA[year] - DA[year]

# Stock-based compensation
# From model: Year 1: 277058.201, Year 2: 316414.3596, Year 3: 370103.242, Year 4: 444032.4968, Year 5: 546083.6278
base_SBC = [277058.201, 316414.3596, 370103.242, 444032.4968, 546083.6278]
SBC = {}
for year in range(1, 6):
    ratio = revenues[year] / base_revenues[year-1]
    SBC[year] = base_SBC[year-1] * ratio

# Adjusted EBITDA = EBITDA + SBC
Adj_EBITDA = {}
for year in range(6):
    if year == 0:
        Adj_EBITDA[year] = EBITDA[year]  # No SBC in year 0
    else:
        Adj_EBITDA[year] = EBITDA[year] + SBC[year]

print('=== MODIFIED SCENARIO ===')
print()
print('Revenues (in millions):')
for y in range(6):
    print(f'  Year {y}: {revenues[y]/1000:.2f}')

print()
print('EBITDA (in millions):')
for y in range(6):
    print(f'  Year {y}: {EBITDA[y]/1000:.2f}')

print()
print('Adjusted EBITDA (in millions):')
for y in range(6):
    print(f'  Year {y}: {Adj_EBITDA[y]/1000:.2f}')

print()
print('Year 5 Adj. EBITDA:', round(Adj_EBITDA[5]/1000, 2))
"
